b:if.b:skin:
  /*!
    * Name      : Hamlet
    * Version   : 1.0.0
    * License   : MIT
    *//*!

  Admin
  =====================
  [boolean] Enable the button to edit widgets
  <Variable name="a.layoutEdit" description="a.layoutEdit" type="string" value="true"/>

  General
  =====================
  [image] Url of default avatar.
  <Variable name="c.avatar" description="c.avatar" type="string" value="https://lh3.googleusercontent.com/a/default-user"/>

  [image] HD Favicon URL.
  <Variable name="c.favicon" description="c.favicon" type="string"/>

  [string] Formspree.io form ID.
  <Variable name="c.formspree" description="c.formspree" type="string"/>

  [string] Image parameters: https://zkreations.com/image-params
  <Variable name="c.imageParams" description="c.imageParams" type="string" value="rw-l60-e30"/>

  [image] Url of default Open Graph image.
  <Variable name="c.ogImage" description="c.ogImage" type="string"/>

  Translatable strings
  =====================
  <Variable name="t.delete" description="t.delete" type="string" value="Delete"/>
  <Variable name="t.reply" description="t.reply" type="string" value="Reply"/>

  Customization
  =====================
  [!] Mandatory variable to enable dynamic layout
  <Variable name="keycolor" description="keycolor" type="color" value="#2196f3" default="#2196f3"/>

  <Group description="Backgrounds">
    <Variable name="body.background" description="Header Background" type="background" color="$(body.background.color)" value="$(color)" default="$(color)"/>
    <Variable name="body.background.color" description="Header color" type="color" value="#7314ff" default="#7314ff"/>
    <Variable name="bg.body" description="Body background color" type="color" value="#fff" default="#fff"/>
    <Variable name="bg.post" description="Post background color" type="color" value="#e0e0e0" default="#e0e0e0"/>
    <Variable name="bg.sidebar" description="Sidebar Background Color" type="color" value="#B6C4F0" default="#B6C4F0"/>
  </Group>
  <Group description="Color">
    <Variable name="primary" description="Accents" type="color" value="#ffffff" default="#ffffff"/>
    <Variable name="color.title" description="Title color" type="color" value="#3a17d7" default="#3a17d7"/>
    <Variable name="color.text" description="Text color" type="color" value="#000450" default="#000450"/>
    <Variable name="color.border" description="Border color" type="color" value="#3a17d7" default="#3a17d7"/>
    <Variable name="color.header.title" description="Header color" type="color" value="#0d0255" default="#0d0255"/>
    <Variable name="color.header.subtitle" description="Description Color" type="color" value="#7B1FA2" default="#7B1FA2"/>
  </Group>
  <Group description="Font">
    <Variable name="font.title" description="Title Font" type="font" value="800 14px var(--font-open-sans)" default="800 14px var(--font-open-sans)"/>
  </Group>
  <Variable name="posts.text.color" description="posts.text.color" hideEditor="true" type="color" value="#777777" default="#777777"/>
  <Variable name="posts.link.color" description="posts.link.color" type="string" value="#666"/>
  <Variable name="posts.text.font" description="posts.text.font" type="string" value="15px Roboto"/>
  <Variable name="posts.background.color" description="posts.background.color" type="string" value="transparent"/>
  <Variable name="posts.title.color" description="posts.title.color" type="string" value="false"/>
  <Variable name="body.link.color" description="body.link.color" type="string" value="false"/>
  <Variable name="body.text.font" description="body.text.font" type="string" value="false"/>

  Skin CSS variables
  =====================*/
  :root {
    /* Font Group */
    --font-title: $(font.title);
    --font-title-family: $(font.title.family);

    /* Color Group */
    --primary: $(primary);
    --color-title: $(color.title);
    --color-text: $(color.text);
    --color-border: $(color.border);
    --color-header-title: $(color.header.title);
    --color-header-subtitle: $(color.header.subtitle);

    /* Backgrounds Group */
    --body-background: $(body.background);
    --body-background-color: $(body.background.color);
    --bg-body: $(bg.body);
    --bg-post: $(bg.post);
    --bg-sidebar: $(bg.sidebar);
  }

  /*
  All styles
  =====================*/
  :root {
  --transition-config: 0.5s cubic-bezier(0.54, 0, 0.1, 1);
  --sidebar-gap: .5rem;
  --form-padding: .75rem 1rem;
  --form-gap: .75rem;
  --comment-gap: 2rem;
  --sidebar-width: 15vw;
  --slide-container: 120vw;
  --main-container: 70vw;
  --card-width: 20vw;
  --bg-header: linear-gradient(90deg,
      rgba(65, 255, 225, 1) 0%,
      rgba(0, 100, 220, 1) 50%,
      rgba(130, 0, 220, 1) 100%);
  --bg-sidebar: #ffffff;
  --bg-footer: #7314ff;
  --typo-border-color: var(--color-border);
  --font-blog-title: "Gajraj One", sans-serif;
  --font-title-family: "Bangers", system-ui;
  --font-open-sans: "Open Sans", sans-serif;
  --font-system: -apple-system, BlinkMacSystemFont,
    "Segoe UI", "Roboto", "Oxygen",
    "Ubuntu", "Cantarell", "Fira Sans",
    "Droid Sans", "Helvetica Neue", sans-serif;
}

html {
  line-height: 1.5;
  -webkit-text-size-adjust: 100%;
  -webkit-font-smoothing: antialiased;
}

*,
::before,
::after {
  box-sizing: border-box;
}

html,
body {
  height: 100%;
}

* {
  margin: 0;
}

fieldset,
legend {
  padding: 0;
}

iframe,
fieldset {
  border-width: 0;
}

a {
  color: inherit;
  text-decoration: none;
}

h1,
h2,
h3,
h4,
h5,
h6 {
  font-size: inherit;
  font-weight: inherit;
  overflow-wrap: break-word;
}

address {
  font-style: normal;
  line-height: inherit;
}

abbr[title] {
  text-decoration: underline dotted;
}

b,
strong {
  font-weight: bolder;
}

small {
  font-size: 80%;
}

sub,
sup {
  font-size: 75%;
  line-height: 0;
  position: relative;
  vertical-align: baseline;
}

sub {
  bottom: -0.25em;
}

sup {
  top: -0.5em;
}

button,
input,
optgroup,
select,
textarea {
  padding: 0;
  border-width: 0;
  font-size: 100%;
  font-family: inherit;
  line-height: inherit;
  color: inherit;
}

textarea:focus,
input:focus {
  outline: none;
}

textarea {
  resize: vertical;
}

button,
select {
  text-transform: none;
}

button,
[type=button],
[type=reset],
[type=submit] {
  -webkit-appearance: button;
  background-color: transparent;
  display: inline-block;
  vertical-align: middle;
}
button:not(:disabled),
[type=button]:not(:disabled),
[type=reset]:not(:disabled),
[type=submit]:not(:disabled) {
  cursor: pointer;
}

progress {
  vertical-align: baseline;
}

::-webkit-file-upload-button {
  -webkit-appearance: button;
  font: inherit;
}

summary {
  display: list-item;
}

[hidden] {
  display: none;
}

ol,
ul,
dl,
dd {
  list-style: none;
  padding: 0;
}

table {
  border-collapse: collapse;
  max-width: 100%;
}

tbody,
td,
th,
thead,
tr {
  border-width: 0;
  text-align: inherit;
}

tr > * {
  padding: 0.75rem;
  word-break: normal;
}

img,
svg,
video,
canvas {
  height: auto;
}

source {
  display: none;
}

img,
svg,
video,
canvas,
iframe,
embed,
object {
  display: block;
  max-width: 100%;
}

audio,
video {
  width: 100%;
}

:where(.item-control, .blog-admin) {
  display: none;
}

:where(.section.no-items) {
  display: none;
}

ins.adsbygoogle[data-ad-status=unfilled] {
  display: none !important;
}

body {
  font-family: var(--font-system);
  background-color: var(--bg-body);
  color: var(--color-text);
}

a {
  color: var(--primary);
}

.container-slideshow {
  display: grid;
  max-width: var(--slide-container, 1200px);
  margin: 0 auto;
  padding: 0 2rem;
  grid-template-columns: 1fr var(--card-width);
}
.container-main {
  display: grid;
  gap: var(--grid-gap, 1rem);
  max-width: var(--main-container, 1200px);
  margin: 0 auto;
  padding: 0 2rem;
  grid-template-columns: var(--sidebar-width) 1fr var(--sidebar-width);
}
.container-main.hide-left {
  grid-template-columns: 1fr var(--sidebar-width, 250px);
}
.container-main.hide-right {
  grid-template-columns: var(--sidebar-width, 250px) 1fr;
}
.container-main.hide-both {
  grid-template-columns: 1fr;
}

.template {
  padding-top: 4rem;
}

.main {
  width: 100%;
  min-width: 0;
  box-sizing: border-box;
}

.btn {
  display: flex;
  padding: var(--form-padding);
  align-items: center;
  gap: var(--form-gap);
}

.cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 16rem), 1fr));
  gap: 1rem;
}

.card {
  background-color: var(--bg-post);
}
.card-content {
  position: relative;
  display: block;
}
.card-content.has-image {
  --card-body-bg: linear-gradient(to bottom, transparent 25%, rgb(0 0 0 / 75%) 100%);
  --color-title: #fff;
  --color-text: #fff;
}
.card-image {
  position: absolute;
  object-fit: cover;
  inset: 0;
  width: 100%;
  height: 100%;
}
.card-meta {
  padding: 3rem;
  background: var(--card-body-bg, transparent);
  aspect-ratio: 9/10;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  position: relative;
}
.card-title {
  font-family: var(--font-title-family);
  color: var(--color-title);
  font-size: 1.45rem;
  font-weight: 800;
}
.card-snippet {
  color: var(--color-text);
  margin-top: 1rem;
  opacity: 0.75;
}

.comments > * + * {
  margin-top: var(--comment-gap);
}
.comments-content > * + * {
  margin-top: var(--comment-gap);
}
.comments-title {
  margin-bottom: 2rem;
  font-size: 1.25rem;
}
.comments-replies {
  margin-top: var(--comment-gap);
  padding-left: 1.5rem;
  border-left: 2px solid var(--color-border);
}
.comments-replies > * + * {
  margin-top: 2rem;
}
.comments-replies:not(:where(.has-reply-form, .has-replies)) {
  display: none;
}

.comment-header {
  display: flex;
  gap: 1rem;
  align-items: center;
  margin-bottom: 1rem;
}
.comment-iframe {
  padding: 1rem;
  background-color: var(--bg-post);
}
.comment-iframe iframe {
  width: 100%;
}
.comment-author {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.comment-badge {
  --i-size: 18px;
}
.comment-time {
  display: block;
}
.comment-footer {
  margin-top: 1rem;
}
.comment-restore-button {
  padding: 1rem;
  width: 100%;
  border: 1px solid var(--color-border);
}
.comment-restore-button:not(.is-replying) {
  display: none;
}
.comment-reply-button {
  padding: 0.25rem 0.75rem;
  margin-right: 0.5rem;
  border: 1px solid var(--color-border);
}

.footer {
  margin: 1rem 2.5rem;
  padding: 2rem 0;
  text-align: center;
  background-color: var(--bg-footer);
  border-radius: 15px 15px 0 0;
}

.form-label {
  display: block;
  margin-bottom: var(--form-gap);
}
.form-section:not(:first-child) {
  margin-top: 1.5rem;
}
.form-control {
  padding: var(--form-padding);
  border: 1px solid var(--color-border);
  width: 100%;
}
.form-control:focus {
  outline: none;
  border-color: var(--primary);
}

.header {
  padding: 1rem 0;
  background: var(--bg-header);
}
.header .section {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 0 2rem;
}
.header .Header {
  flex: 1;
}
.header .header-wrapper {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}
.header .header-title {
  margin: 0;
  font-size: 1.75rem;
  line-height: 1;
  font-family: var(--font-blog-title);
}
.header .header-title a {
  color: var(--color-header-title);
  text-decoration: none;
}
.header .header-subtitle {
  margin-top: 0.75rem;
  font-size: 1rem;
  line-height: 1.2;
  color: var(--color-header-subtitle);
  font-family: var(--font-blog-title);
}
.header .header-bars {
  left: 2rem;
}
.header .header-bars::before {
  pointer-events: var(--switch-bars, none);
  opacity: var(--switch-bars, 0);
}
.header .header-search {
  right: 2rem;
}
.header .header-search::before {
  pointer-events: var(--switch-search, none);
  opacity: var(--switch-search, 0);
}
.header .google-auto-placed {
  display: none !important;
}

.i {
  stroke-width: var(--i-stroke, 2);
  width: var(--i-size, 24px);
  height: var(--i-size, 24px);
}

.message {
  text-align: center;
  font-size: 1.25rem;
}

.blog-pager {
  margin-top: 2.5rem;
  display: flex;
  justify-content: center;
  gap: 1rem;
}

.pager-button {
  color: var(--color-text);
  display: flex;
  align-items: center;
  gap: 0.5rem;
  border: 1px solid var(--color-border);
  padding: 0.75rem;
}
.pager-button:hover {
  color: var(--primary);
}

.post {
  margin-left: auto;
  margin-right: auto;
  max-width: 720px;
}
.post-header {
  padding-bottom: 2rem;
  text-align: center;
}
.post-date {
  margin-top: 0.5rem;
  display: block;
  text-transform: capitalize;
}
.post-title {
  color: var(--color-title);
  font-size: 2.5rem;
  font-family: var(--font-title-family);
  font-weight: 800;
}
.post-body {
  line-height: 1.75;
  font-size: 1.125rem;
}
.post-body :where(h1, h2, h3, h4, h5, h6) {
  font-family: var(--font-title-family);
  color: var(--color-title);
}
.post-comment {
  margin-top: 2rem;
}

.search-input {
  padding: 0.7rem 0.8rem;
  background-color: #f1f1f1;
  color: #444;
  border: 1px solid #ddd;
  border-radius: 2px;
  transition: background-color var(--transition-config), border-color var(--transition-config), color var(--transition-config);
}
.search-input::placeholder {
  color: #888;
}
.search-input:focus {
  outline: none;
  background-color: #e9e9e9;
  border-color: #ccc;
}

.left-sidebar,
.right-sidebar {
  background-color: var(--bg-sidebar, #ffffff);
  border-radius: 15px;
  padding: var(--sidebar-gap, 0.5rem);
  overflow-y: auto;
  min-height: 100%;
}
.left-sidebar > * + *,
.right-sidebar > * + * {
  border-top: 1px solid var(--color-border, #ddd);
  padding-top: var(--sidebar-gap, 1rem);
  margin-top: var(--sidebar-gap, 1rem);
}
.left-sidebar,
.right-sidebar {
  width: 100%;
  box-sizing: border-box;
}

.left-sidebar.hidden,
.right-sidebar.hidden {
  display: none;
}

.switch {
  position: absolute;
  color: #fff;
  top: 2rem;
  cursor: pointer;
}
.switch::before {
  position: fixed;
  inset: 0;
  background-color: rgba(0, 0, 0, 0.5);
  transition: opacity var(--transition-config);
  cursor: default;
  content: "";
  z-index: 5;
}
.switch-control {
  display: none;
}
.switch-sidebar:checked ~ :where(.offcanvas, .header) {
  --switch-sidebar-position: 0;
  --switch-bars: 1;
}
.switch-search:checked ~ :where(.offcanvas, .header) {
  --switch-search-position: -50%;
  --switch-search: 1;
}

.widget {
  margin-bottom: 1rem;
}
.widget-title {
  font-weight: 500;
}

.pages {
  display: flex;
  gap: 0.5rem;
}
.pages:not(.pages-header) {
  flex-direction: column;
}
.pages-header {
  justify-content: center;
  padding-top: 0.5rem;
  padding-bottom: 0.5rem;
}
.pages-link {
  font-size: 1.125rem;
  color: var(--color-text);
}
.pages-link:hover, .pages-link.is-here {
  color: var(--primary);
}

.labels {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  width: 100%;
}
.labels-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  min-height: 40px;
  box-sizing: border-box;
  padding: 0.65rem 0.8rem;
  background-color: #f1f1f1;
  border: 0;
  border-radius: 0;
  color: #444;
  font-size: 0.75rem;
  font-weight: 400;
  text-transform: none;
  text-decoration: none;
  transition: background-color var(--transition-config), color var(--transition-config);
}
.labels-link:hover, .labels-link.is-here {
  background-color: #e8e8e8;
  border-color: transparent;
  color: var(--primary);
}

.profile-image {
  float: left;
  margin-right: 1rem;
}
.profile-image img {
  border-radius: 50rem;
}

.hierarchy-list {
  border-inline-start: 2px solid var(--color-border);
  padding-inline-start: 1rem;
}
.hierarchy-date {
  margin-bottom: 0.5rem;
  display: block;
}
.hierarchy-name {
  color: var(--color-title);
  text-transform: capitalize;
  font-weight: 500;
}
.hierarchy-content {
  margin-bottom: 0.5rem;
}
.hierarchy-post-link {
  color: var(--color-text);
}
.hierarchy-post-link:hover {
  color: var(--primary);
}

.media-caption {
  color: var(--color-text);
  margin-top: 0.5rem;
}

.contact-form {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.links-link {
  margin: 0 0.2rem;
}

.links-social {
  display: flex;
}

.text-left {
  text-align: left;
}

.text-right {
  text-align: right;
}

.text-center {
  text-align: center;
}

.text-justify {
  text-align: justify;
}

.capitalize {
  text-transform: capitalize;
}

.uppercase {
  text-transform: uppercase;
}

.lowercase {
  text-transform: lowercase;
}

.fs-1 {
  font-size: 2.5rem;
}

.fs-2 {
  font-size: 2rem;
}

.fs-3 {
  font-size: 1.5rem;
}

.fs-4 {
  font-size: 1.25rem;
}

.fs-5 {
  font-size: 1.125rem;
}

.fs-6 {
  font-size: 1rem;
}

.fs-7 {
  font-size: 0.875rem;
}

.fs-8 {
  font-size: 0.75rem;
}
  @layer typography {
  :root {
    --typo-border-color: #d4d4d4;
    --typo-caption-size: 0.875rem;
    --typo-caption-spacing: 0.75rem;
    --typo-code-background: #f5f5f5;
    --typo-code-padding: 1rem;
    --typo-column-min: 200px;
    --typo-gallery-caption-background: linear-gradient(#0000, #0006);
    --typo-gallery-caption-color: white;
    --typo-gallery-caption-padding: 0.75rem;
    --typo-gallery-min: 200px;
    --typo-gallery-spacing: 2px;
    --typo-heading-spacing: 1rem;
    --typo-initial-letter: 3;
    --typo-spacing: 1.5rem;
    --typo-spoiler-collapse-text: "Collapse";
    --typo-spoiler-expand-text: "Expand";
    --typo-spoiler-padding: 1rem;
    --typo-table-cell-padding: .5rem;
  }
}
.typography * {
  margin: 0;
  box-sizing: border-box;
}
.typography :where(hr) {
  height: 0;
  border-width: 0;
  border-top: 1px solid var(--typo-border-color);
  margin-top: var(--typo-spacing);
}
.typography :where(br:not(p > br)) {
  display: none;
}
.typography > *:not(:where(:last-child)) {
  margin-bottom: var(--typo-spacing);
}
.typography :where(p, hr, figure, img, blockquote, ul, ol, pre, table, video, audio, iframe, details, div[class*=typo-]):not(:where(video[class], audio[class], :last-child, :where(figure, blockquote) :last-of-type)) {
  margin-bottom: var(--typo-spacing);
}

.typography :where(pre:has(> code)) {
  border-inline-start: 3px solid var(--typo-border-color);
  background-color: var(--typo-code-background);
  padding: var(--typo-code-padding);
  font-size: 1rem;
  overflow-x: auto;
}
.typography :where(code) {
  background: var(--typo-code-background);
}

.typography :where(h1, h2, h3, h4, h5, h6) {
  margin-bottom: var(--typo-heading-spacing);
  font-weight: 500;
  line-height: 1.5;
}
.typography :where(h1) {
  font-size: clamp(1.75rem, 5vw, 2.25rem);
}
.typography :where(h2) {
  font-size: clamp(1.5rem, 4.25vw, 1.875rem);
}
.typography :where(h3) {
  font-size: clamp(1.25rem, 3.75vw, 1.625rem);
}
.typography :where(h4) {
  font-size: clamp(1.125rem, 3.25vw, 1.375rem);
}
.typography :where(h5) {
  font-size: clamp(1rem, 2.75vw, 1.25rem);
}
.typography :where(h6) {
  font-size: clamp(0.875rem, 2.5vw, 1.125rem);
}

.typography :where(table) {
  border-collapse: collapse;
}
.typography :where(tr > *) {
  padding: var(--typo-table-cell-padding);
  border: 1px solid var(--typo-border-color);
  word-break: normal;
}
.typography :where(blockquote) {
  border-inline-start: 3px solid var(--typo-border-color);
  padding-inline-start: var(--typo-spacing);
}
.typography :where(ul, ol) {
  padding-inline-start: var(--typo-spacing);
}
.typography :where(ul) {
  list-style-type: square;
}
.typography :where(ol) {
  list-style-type: decimal;
}

.typography :where(figure) {
  width: max-content;
}
.typography :where(figcaption) {
  text-align: center;
  margin-top: var(--typo-caption-spacing);
  font-size: var(--typo-caption-size);
}
.typography :where(img, video, iframe, figure) {
  display: block;
  max-width: 100%;
  height: auto;
}
.typography :where(audio) {
  width: 100%;
}
.typography :where(iframe[src*=vimeo i], iframe[src*=youtube i], video) {
  aspect-ratio: 16/9;
  width: 100%;
  height: auto;
}

.typo-align-left {
  float: inline-start;
  clear: inline-start;
  margin-inline-end: var(--typo-spacing);
}
.typo-align-right {
  float: inline-end;
  clear: inline-end;
  margin-inline-start: var(--typo-spacing);
}
.typo-align-center {
  margin-left: auto;
  margin-right: auto;
  display: grid;
  place-content: center;
}
.typo-align-full {
  width: 100%;
}

.typo-columns {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: var(--typo-spacing);
}
.typo-columns > * {
  flex: 1 1 var(--typo-column-min);
  margin-bottom: 0;
}

.typo-gallery {
  display: flex;
  flex-wrap: wrap;
  gap: var(--typo-gallery-spacing);
}
.typo-gallery > * {
  flex: 1 1 var(--typo-gallery-min);
  margin-bottom: 0;
}
.typo-gallery :where(img) {
  object-fit: cover;
  width: 100%;
  height: 100%;
}
.typo-gallery :where(figure) {
  position: relative;
}
.typo-gallery :where(figcaption) {
  background: var(--typo-gallery-caption-background);
  color: var(--typo-gallery-caption-color);
  padding: var(--typo-gallery-caption-padding);
  position: absolute;
  inset: auto 0 0;
}

.typo-drop-cap::first-letter {
  margin-inline-end: 1em;
  initial-letter: var(--typo-initial-letter);
}

.typo-spoiler {
  padding: var(--typo-spoiler-padding);
  border-top: 1px solid var(--typo-border-color);
  border-bottom: 1px solid var(--typo-border-color);
}
.typo-spoiler :where(summary) {
  display: flex;
  justify-content: space-between;
  align-items: center;
  cursor: pointer;
}
.typo-spoiler :where(summary)::after {
  content: var(--typo-spoiler-expand-text);
}
.typo-spoiler:where([open]) > :where(summary) {
  margin-bottom: var(--typo-spacing);
}
.typo-spoiler:where([open]) > :where(summary)::after {
  content: var(--typo-spoiler-collapse-text);
}
.typo-spoiler:where([name]):where(:has(+ .typo-spoiler)) {
  margin-bottom: 0;
  border-bottom: 0;
}

.typo-table {
  overflow-x: auto;
}
.typo-table-fixed {
  table-layout: fixed;
  width: 100%;
}


